function fdEdmRoundQuote(q){const sign=q.n<0n?-1n:1n,n=q.n*sign;return sign*((n*200n+q.s)/(q.s*2n));}
function fdEdmFormatQuote(q){const cents=fdEdmRoundQuote(q),sign=cents<0n?'-':'',abs=cents<0n?-cents:cents;return sign+(abs/100n).toLocaleString('tr-TR')+','+(abs%100n).toString().padStart(2,'0')+' '+q.currency;}
function fdEdmBaseQuote(row){try{return{...fdEdmDecimal(row.price),currency:row.currency}}catch(_){return null}}
function fdEdmRate(row,currency,chosen='auto'){const source=(!currency&&chosen==='auto')?(row.exchangeRates||[]):(row.effectiveExchangeRates||row.exchangeRates||[]),rates=source.filter(r=>(currency?r.currency===currency:chosen==='auto'||r.currency===chosen));if(rates.length!==1)return null;try{const d=fdEdmDecimal(rates[0].tryPerUnit);return d.n>0n?{...d,currency:rates[0].currency}:null}catch(_){return null}}
