function fdEdmPriceColumns(row,firm){const base=fdEdmBaseQuote(row);if(!base)return ['Geçersiz fiyat','-'];if(!firm?.foreignCurrencyEnabled)return [fdEdmFormatQuote(base),'-'];if(row.currency!=='TRY'){const rate=fdEdmRate(row,row.currency);return [rate?fdEdmFormatQuote({n:base.n*rate.n,s:base.s*rate.s,currency:'TRY'}):'Kur bulunamadı',fdEdmFormatQuote(base)]}const fx=fdEdmForeignQuote(row,firm);return [fdEdmFormatQuote(base),fx?fdEdmFormatQuote(fx):'Kur bulunamadı'];}
