 const company=activeUser.sirketId,{data,error}=await fdAyarBekle(supabaseClient.from('fd_edm_status').select('state,message,checked_at,next_check_at,counters').eq('company_id',company).maybeSingle());if(error)throw error;
 const el=fdEdmEl('runtimeStatus');if(el){if(!data)el.textContent='EDM görevi henüz durum bildirmedi.';else{const labels={running:'Çalışıyor',ready:'Kontrol tamamlandı',paused:'Duraklatıldı',error:'Kontrol tamamlanamadı',login_required:'EDM bağlantısı kontrol edilmeli',partial:'Raporlar hazırlanıyor'};const age=Date.now()-Date.parse(data.checked_at),c=data.counters||{};el.textContent=(labels[data.state]||data.state)+' · '+data.message+' · Son durum: '+new Date(data.checked_at).toLocaleString('tr-TR')+(age>Math.max(10,fdEdmConfig().intervalMinutes*2)*60000?' · İşleyici uzun süredir durum bildirmedi.':'')+(c.scanned?' · Taranan: '+c.scanned:'')+(c.imported?' · Yeni kayıt: '+c.imported:'')+' · Sepette: '+(c.queued||0)+' · Toplu gönderim: 20:00'+(c.sent?' · Gönderilen: '+c.sent:'')+(data.next_check_at?' · Sonraki kontrol: '+new Date(data.next_check_at).toLocaleString('tr-TR'):'')}}
 const host=fdEdmEl('invoiceList');if(!host)return;const response=await fdAyarBekle(supabaseClient.from('fd_edm_invoices').select('uuid,number,invoice_date,supplier_vkn,metadata,pdf_path,report_paths').eq('company_id',company).order('invoice_date',{ascending:false}).order('number',{ascending:false}).limit(200));if(response.error)throw response.error;fdEdmArchiveRows=response.data||[];fdEdmRenderArchive();await fdEdmReadBasket(fdEdmArchiveRows);
