function fdEdmCloseInvoice(){fdEdmInvoiceRequest++;const dialog=fdEdmEl('invoiceDialog');if(dialog?.open)dialog.close();fdEdmEl('invoiceDetails')?.replaceChildren();}
async function fdEdmShowInvoice(invoice){
 fdAyarDogrula();const host=fdEdmEl('invoiceDetails'),dialog=fdEdmEl('invoiceDialog'),request=++fdEdmInvoiceRequest;host.replaceChildren();fdEdmEl('invoiceTitle').textContent=invoice.number+' · '+invoice.invoice_date;if(!dialog.open)dialog.showModal();
 const supplier=document.createElement('p');supplier.className='fd-edm-muted';supplier.textContent=invoice.metadata?.supplier||invoice.supplier_vkn;host.append(supplier);
 const current=()=>fdAyarGecerli()&&request===fdEdmInvoiceRequest&&dialog.open;
 try{
 if(invoice.pdf_path){if(!invoice.pdf_path.startsWith(activeUser.sirketId+'/'))throw Error('Şirket faturası eşleşmiyor.');const {data,error}=await fdAyarBekle(supabaseClient.storage.from('fd-edm-private').createSignedUrl(invoice.pdf_path,300));if(!current())return;if(error)throw error;const a=document.createElement('a');a.href=data.signedUrl;a.target='_blank';a.rel='noopener noreferrer';a.textContent='Faturanın PDF dosyasını aç';host.append(a)}
 for(const object of invoice.report_paths||[]){if(!object.startsWith(activeUser.sirketId+'/'))throw Error('Şirket raporu eşleşmiyor.');const {data,error}=await fdAyarBekle(supabaseClient.storage.from('fd-edm-private').createSignedUrl(object,300));if(!current())return;if(error)throw error;const img=document.createElement('img');img.src=data.signedUrl;img.alt=invoice.number+' fatura görseli ve fiyat raporu';host.append(img)}
 const firm=fdEdmConfig().suppliers.find(f=>f.vkn===invoice.supplier_vkn);
 for(const product of invoice.metadata?.products||[]){const section=document.createElement('section'),h=document.createElement('h4');h.textContent=product.name+' · '+fdEdmUnit(product.unit);section.append(h);const table=document.createElement('table'),tr=table.createTHead().insertRow();for(const text of ['Tarih','Fatura no','Fiyat','Döviz fiyatı']){const th=document.createElement('th');th.textContent=text;tr.append(th)}const body=table.createTBody(),history=product.history||[];for(const [i,price]of history.entries()){const r=body.insertRow();if(fdEdmRising(price,history[i+1],firm)){r.className='fd-edm-price-rise';r.title='Önceki alıma göre fiyat artışı'}for(const text of [price.date,price.number,...fdEdmPriceColumns(price,firm)])r.insertCell().textContent=text}section.append(table);host.append(section)}
 }catch(e){if(current()){const error=document.createElement('p');error.dataset.error='true';error.setAttribute('role','alert');error.textContent='Fatura detayı yüklenemedi: '+e.message;host.append(error)}}
}
async function fdEdmCommand(action){fdAyarDogrula(true);const c=fdEdmConfig();if(action==='pause')c.automaticImportEnabled=false;else if(action==='resume'){c.automaticImportEnabled=true;c.checkRequestedAt=new Date().toISOString()}else c.checkRequestedAt=new Date().toISOString();await fdEdmPersist(c);fdEdmRenderLists();fdEdmMessage(action==='pause'?'Fatura takibi duraklatıldı. Günlük grup raporu etkilenmez.':'Komut kaydedildi; mevcut WhatsApp aracındaki EDM görevi en geç bir dakika içinde alacak.');}

