    host.append(fdEdmPanel);fdEdmBind(fdEdmEl('archiveSearch'),'input',fdEdmRenderArchive);fdEdmBind(fdEdmEl('closeInvoice'),'click',fdEdmCloseInvoice);fdEdmBind(fdEdmEl('invoiceDialog'),'close',()=>{if(!fdEdmEl('invoiceDialog')?.open){fdEdmInvoiceRequest++;fdEdmEl('invoiceDetails')?.replaceChildren()}});
