    fdEdmBind(fdEdmEl('saveFirm'),'click',async()=>{fdAyarDogrula(true);if(fdEdmLoading)throw Error('Kayıtlı firmaların yüklenmesini bekleyin.');const c=fdEdmConfig(),vkn=fdEdmEl('vkn').value.trim(),name=fdEdmEl('firmName').value.trim(),whatsapp=fdEdmEl('whatsappEnabled').checked;if(!/^\d{10,11}$/.test(vkn)||!name)throw Error('10 haneli vergi numarası veya 11 haneli T.C. kimlik numarası ve firma adı girin.');if(fdEdmEditingVkn&&vkn!==fdEdmEditingVkn)throw Error('Düzenlenen firmanın vergi numarası değiştirilemez.');if(!fdEdmEditingVkn&&c.suppliers.some(f=>f.vkn===vkn))throw Error('Bu firma zaten kayıtlı; listedeki Düzenle düğmesini kullanın.');const selected=Array.from(fdEdmEl('firmRecipients').querySelectorAll('input:checked')).map(e=>e.value);if(whatsapp&&!c.recipients.some(r=>r.enabled&&selected.includes(r.id)))throw Error('WhatsApp raporu için en az bir aktif alıcı seçin.');const old=c.suppliers.find(f=>f.vkn===vkn);c.suppliers=c.suppliers.filter(f=>f.vkn!==vkn).concat({...old,vkn,name,enabled:fdEdmEl('trackEnabled').checked,whatsappReportEnabled:whatsapp,foreignCurrencyEnabled:fdEdmEl('foreignCurrencyEnabled').checked,foreignCurrency:fdEdmEl('foreignCurrency').value});const previous=c.rules.filter(r=>r.vkn===vkn);c.rules=c.rules.filter(r=>r.vkn!==vkn).concat(previous.map(r=>({...r,enabled:whatsapp&&selected.includes(r.recipientId)})));for(const id of selected)if(whatsapp&&!previous.some(r=>r.recipientId===id))c.rules.push({vkn,recipientId:id,enabled:true});await fdEdmPersist(c);fdEdmEditFirm(c.suppliers.find(f=>f.vkn===vkn));fdEdmMessage('Firma, fatura takibi ve WhatsApp raporu tercihleri kaydedildi.');});
